const TOKEN_KEY = '{{TOKEN_KEY_PREFIX}}_access_token';
const USER_KEY = '{{TOKEN_KEY_PREFIX}}_user';
const RETURN_KEY = '{{TOKEN_KEY_PREFIX}}_return_path';
const VERIFIER_KEY = '{{TOKEN_KEY_PREFIX}}_pkce_verifier';
const TRANSACTION_KEY = '{{TOKEN_KEY_PREFIX}}_oidc_transactions';
const TRANSACTION_TTL_MS = 15 * 60 * 1000;
const AUTH_EVENT = '{{TOKEN_KEY_PREFIX}}:auth:changed';
const DEFAULT_RETURN_PATH = '{{AUTH_DEFAULT_ROUTE}}';

function generateVerifier() {
  const array = new Uint8Array(96);
  window.crypto.getRandomValues(array);
  return btoa(String.fromCharCode(...array))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

async function generateChallenge(verifier) {
  const data = new TextEncoder().encode(verifier);
  const digest = await window.crypto.subtle.digest('SHA-256', data);
  return btoa(String.fromCharCode(...new Uint8Array(digest)))
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=+$/, '');
}

function parseJsonObject(raw) {
  if (!raw) return {};
  try {
    const parsed = JSON.parse(raw);
    return parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
  } catch {
    return {};
  }
}

function pruneTransactions(transactions, now = Date.now()) {
  return Object.fromEntries(
    Object.entries(transactions).filter(([, transaction]) => {
      if (!transaction || typeof transaction !== 'object') return false;
      if (typeof transaction.verifier !== 'string' || !transaction.verifier) return false;
      const createdAt = Number(transaction.createdAt || 0);
      return createdAt > 0 && now - createdAt <= TRANSACTION_TTL_MS;
    }),
  );
}

function readTransactions() {
  return pruneTransactions(parseJsonObject(sessionStorage.getItem(TRANSACTION_KEY)));
}

function writeTransactions(transactions) {
  const pruned = pruneTransactions(transactions);
  if (Object.keys(pruned).length === 0) {
    sessionStorage.removeItem(TRANSACTION_KEY);
    return;
  }
  sessionStorage.setItem(TRANSACTION_KEY, JSON.stringify(pruned));
}

function safeReturnPath(value) {
  if (typeof value !== 'string') return DEFAULT_RETURN_PATH;
  if (!value.startsWith('/') || value.startsWith('//')) return DEFAULT_RETURN_PATH;
  return value;
}

function writeAuthTransaction(transaction) {
  const transactions = readTransactions();
  transactions[transaction.state] = transaction;
  writeTransactions(transactions);
}

function readAuthTransaction(state) {
  if (!state) return null;
  const transactions = readTransactions();
  const transaction = transactions[state];
  writeTransactions(transactions);
  return transaction || null;
}

function readLegacyTransaction() {
  const verifier = sessionStorage.getItem(VERIFIER_KEY);
  if (!verifier) return null;
  return {
    state: '',
    verifier,
    returnPath: safeReturnPath(sessionStorage.getItem(RETURN_KEY) || DEFAULT_RETURN_PATH),
    createdAt: Date.now(),
  };
}

function clearAuthTransaction(state = '') {
  if (state) {
    const transactions = readTransactions();
    delete transactions[state];
    writeTransactions(transactions);
  } else {
    sessionStorage.removeItem(TRANSACTION_KEY);
  }
  sessionStorage.removeItem(VERIFIER_KEY);
  sessionStorage.removeItem(RETURN_KEY);
}

function decodeJwtPayload(token) {
  try {
    const [, payload] = token.split('.');
    const padded = payload.replace(/-/g, '+').replace(/_/g, '/');
    return JSON.parse(atob(padded));
  } catch {
    return null;
  }
}

function isTokenExpired(token) {
  const payload = decodeJwtPayload(token);
  if (!payload?.exp) return false;
  return Date.now() / 1000 > payload.exp - 30;
}

function userFromPayload(payload) {
  if (!payload) return null;
  const sub = payload.sub || payload.user_id || payload.email;
  return {
    id: sub,
    user_id: sub,
    email: payload.email || null,
    name: payload.name || payload.preferred_username || payload.email || sub,
    firstName: payload.given_name || null,
    lastName: payload.family_name || null,
    roles: payload.realm_access?.roles || payload.roles || [],
  };
}

