function createOidcAdapter({ authority, discoveryUrl, clientId, redirectUri, scope }) {
  const listeners = new Set();
  let metadataPromise = null;

  function resolveDiscoveryUrl() {
    if (discoveryUrl) return discoveryUrl;
    const cleanAuthority = authority.replace(/\/$/, '');
    if (cleanAuthority.endsWith('/.well-known/openid-configuration')) {
      return cleanAuthority;
    }
    return `${cleanAuthority}/.well-known/openid-configuration`;
  }

  async function resolveMetadata() {
    if (!metadataPromise) {
      metadataPromise = fetch(resolveDiscoveryUrl(), {
        headers: { Accept: 'application/json' },
      }).then(async (res) => {
        if (!res.ok) {
          const body = await res.text().catch(() => '');
          throw new Error(`OIDC discovery failed: HTTP ${res.status} ${body}`.trim());
        }
        const metadata = await res.json();
        if (!metadata.authorization_endpoint || !metadata.token_endpoint) {
          throw new Error('OIDC discovery document is missing authorization_endpoint or token_endpoint');
        }
        return metadata;
      });
    }
    return metadataPromise;
  }

  function notify() {
    window.dispatchEvent(new CustomEvent(AUTH_EVENT));
  }

  function getStoredToken() {
    return sessionStorage.getItem(TOKEN_KEY);
  }

  function getStoredUser() {
    try {
      const raw = sessionStorage.getItem(USER_KEY);
      return raw ? JSON.parse(raw) : null;
    } catch {
      return null;
    }
  }

  function clearStoredUserSession() {
    sessionStorage.removeItem(TOKEN_KEY);
    sessionStorage.removeItem(USER_KEY);
  }

  function clearSession() {
    clearStoredUserSession();
    clearAuthTransaction();
  }

  return {
    getCurrentUser: async () => {
      const token = getStoredToken();
      if (!token || isTokenExpired(token)) {
        clearStoredUserSession();
        return null;
      }
      const stored = getStoredUser();
      if (stored) return stored;
      const payload = decodeJwtPayload(token);
      return userFromPayload(payload);
    },

    onAuthStateChange: (callback) => {
      const handler = async () => {
        const token = getStoredToken();
        if (token && !isTokenExpired(token)) {
          const user = getStoredUser() || userFromPayload(decodeJwtPayload(token));
          callback(user);
        } else {
          callback(null);
        }
      };
      listeners.add(handler);
      window.addEventListener(AUTH_EVENT, handler);
      handler();

      return () => {
        listeners.delete(handler);
        window.removeEventListener(AUTH_EVENT, handler);
      };
    },

    login: async () => {
      const metadata = await resolveMetadata();
      const returnPath = safeReturnPath(window.location.pathname + window.location.search);

      const verifier = generateVerifier();
      const challenge = await generateChallenge(verifier);
      const state = generateVerifier();
      writeAuthTransaction({
        state,
        verifier,
        returnPath,
        createdAt: Date.now(),
      });

      // Compatibility fallback for callbacks already in flight during a deploy.
      sessionStorage.setItem(VERIFIER_KEY, verifier);
      sessionStorage.setItem(RETURN_KEY, returnPath);

      const params = new URLSearchParams({
        client_id: clientId,
        redirect_uri: redirectUri,
        response_type: 'code',
        scope,
        code_challenge: challenge,
        code_challenge_method: 'S256',
        state,
      });

      window.location.href = `${metadata.authorization_endpoint}?${params.toString()}`;
    },

    logout: async () => {
      let metadata = null;
      try {
        metadata = await resolveMetadata();
      } catch {
        metadata = null;
      }
      const token = getStoredToken();
      clearSession();
      notify();

      if (!metadata?.end_session_endpoint) {
        window.location.href = '/login';
        return;
      }

      const params = new URLSearchParams({
        client_id: clientId,
        post_logout_redirect_uri: window.location.origin + '/login',
      });

      if (token) {
        params.set('id_token_hint', token);
      }

      window.location.href = `${metadata.end_session_endpoint}?${params.toString()}`;
    },

    getAccessToken: () => {
      const token = getStoredToken();
      return token && !isTokenExpired(token) ? token : null;
    },

    handleCallback: async () => {
      const metadata = await resolveMetadata();
      const params = new URLSearchParams(window.location.search);
      const code = params.get('code');
      if (!code) throw new Error('No authorization code in callback URL');

      const state = params.get('state') || '';
      const transaction = readAuthTransaction(state) || (!state ? readLegacyTransaction() : null);
      if (state && transaction?.state && transaction.state !== state) {
        throw new Error('Login state mismatch - restart sign-in');
      }

      const verifier = transaction?.verifier;
      if (!verifier) throw new Error('PKCE verifier missing - login session expired');

      const body = new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: clientId,
        redirect_uri: redirectUri,
        code,
        code_verifier: verifier,
      });

      const res = await fetch(metadata.token_endpoint, {
        method: 'POST',
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
        body: body.toString(),
      });

      if (!res.ok) {
        const err = await res.text();
        throw new Error(`Token exchange failed: ${err}`);
      }

      const data = await res.json();
      const accessToken = data.access_token;
      const idToken = data.id_token;

      sessionStorage.setItem(TOKEN_KEY, accessToken);
      clearAuthTransaction(state);

      const payload = decodeJwtPayload(idToken || accessToken);
      const user = userFromPayload(payload);
      if (user) {
        sessionStorage.setItem(USER_KEY, JSON.stringify(user));
      }

      notify();
      return { returnPath: safeReturnPath(transaction?.returnPath || DEFAULT_RETURN_PATH) };
    },
  };
}

export function createAuthAdapter() {
  const mockMode = import.meta.env.VITE_MOCK_MODE === 'true';
  const authority = import.meta.env.VITE_OIDC_AUTHORITY || '';
  const discoveryUrl = import.meta.env.VITE_OIDC_DISCOVERY_URL || '';
  const clientId = import.meta.env.VITE_OIDC_CLIENT_ID || '{{OIDC_CLIENT_ID}}';
  const scope = import.meta.env.VITE_OIDC_SCOPE || 'openid profile email';
  const redirectUri = import.meta.env.VITE_OIDC_REDIRECT_URI
    || `${window.location.origin}/auth/callback`;

  if (mockMode) {
    return createMockAdapter();
  }

  if (!authority && !discoveryUrl) {
    throw new Error(
      '[{{APP_SLUG}}] VITE_OIDC_AUTHORITY or VITE_OIDC_DISCOVERY_URL is required. ' +
      'Set one to your OIDC provider, or set VITE_MOCK_MODE=true for local development.',
    );
  }

  return createOidcAdapter({ authority, discoveryUrl, clientId, redirectUri, scope });
}
